package com.setuppicker;

import java.awt.Canvas;
import java.awt.event.InputEvent;
import java.awt.event.KeyEvent;
import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;

public class PickerInputTest
{
	private final Canvas canvas = new Canvas();
	private int platformModifier = InputEvent.CTRL_DOWN_MASK;
	private boolean requireModifier = true;
	private PickerModel model;
	private PickerInput input;

	@Before
	public void setUp()
	{
		final Client client = (Client) Proxy.newProxyInstance(getClass().getClassLoader(), new Class<?>[]{Client.class},
			(proxy, method, args) ->
			{
				switch (method.getName())
				{
					case "getCanvas":
						return canvas;
					case "getGameState":
						return GameState.LOGGED_IN;
					default:
						throw new UnsupportedOperationException(method.getName());
				}
			});
		final SetupPickerConfig config = new SetupPickerConfig()
		{
			@Override
			public boolean requireModifier()
			{
				return requireModifier;
			}
		};
		model = new PickerModel();
		final List<SetupEntry> setups = new ArrayList<>();
		for (String name : new String[]{"Vorkath", "Zulrah", "Wintertodt", "Slayer", "Barrows"})
		{
			setups.add(new SetupEntry(name, false, null, 1));
		}
		model.setSetups(setups);
		model.setVisibleRows(5);
		input = new PickerInput(client, null, config, new SetupPickerOverlay(client, config, model, null), model,
			new PlatformModifier(null)
			{
				@Override
				public int get()
				{
					return platformModifier;
				}
			});
	}

	/**
	 * Delivers a key event the way KeyManager would.
	 *
	 * @param physicalKey the key actually pressed, which real events carry as the extended key code
	 * @param keyCode     the event's key code, which differs from physicalKey once a remapping plugin has had it
	 * @return whether the picker consumed the event
	 */
	private boolean send(int id, int modifiers, int physicalKey, int keyCode, char keyChar)
	{
		final KeyEvent e = new KeyEvent(canvas, id, 0, modifiers, keyCode, keyChar)
		{
			@Override
			public int getExtendedKeyCode()
			{
				return physicalKey;
			}
		};
		switch (id)
		{
			case KeyEvent.KEY_PRESSED:
				input.keyPressed(e);
				break;
			case KeyEvent.KEY_TYPED:
				input.keyTyped(e);
				break;
			default:
				input.keyReleased(e);
				break;
		}
		return e.isConsumed();
	}

	private boolean send(int id, int modifiers, int keyCode, char keyChar)
	{
		return send(id, modifiers, keyCode, keyCode, keyChar);
	}

	// a full press, type, release of a character key, as AWT delivers it
	private void tap(int keyCode, char c)
	{
		assertTrue(send(KeyEvent.KEY_PRESSED, 0, keyCode, c));
		assertTrue(send(KeyEvent.KEY_TYPED, 0, KeyEvent.VK_UNDEFINED, c));
		assertTrue(send(KeyEvent.KEY_RELEASED, 0, keyCode, c));
	}

	private void openWithHotkey()
	{
		assertTrue(send(KeyEvent.KEY_PRESSED, InputEvent.CTRL_DOWN_MASK, KeyEvent.VK_K, (char) 0x0b));
		assertTrue(send(KeyEvent.KEY_TYPED, InputEvent.CTRL_DOWN_MASK, KeyEvent.VK_UNDEFINED, (char) 0x0b));
		assertTrue(send(KeyEvent.KEY_RELEASED, InputEvent.CTRL_DOWN_MASK, KeyEvent.VK_K, (char) 0x0b));
		assertTrue(model.view().isPaletteOpen());
	}

	@Test
	public void keysPassThroughWhileClosed()
	{
		assertFalse(send(KeyEvent.KEY_PRESSED, 0, KeyEvent.VK_W, 'w'));
		assertFalse(send(KeyEvent.KEY_TYPED, 0, KeyEvent.VK_UNDEFINED, 'w'));
		assertFalse(send(KeyEvent.KEY_RELEASED, 0, KeyEvent.VK_W, 'w'));
		assertFalse(send(KeyEvent.KEY_PRESSED, 0, KeyEvent.VK_ENTER, '\n'));
	}

	@Test
	public void typingFiltersWithoutDoubling()
	{
		openWithHotkey();
		tap(KeyEvent.VK_S, 's');
		tap(KeyEvent.VK_W, 'w');
		assertEquals("sw", model.view().getQuery());
		assertEquals(0, model.view().getSelected());
		tap(KeyEvent.VK_BACK_SPACE, '\b');
		assertEquals("s", model.view().getQuery());
		assertEquals(2, model.view().getSetups().size());
	}

	@Test
	public void keysRewrittenByKeyRemappingAreStillTyped()
	{
		openWithHotkey();
		// Key Remapping has turned S into Down and W into Up, blanked their characters, and consumed the
		// typed events, so those never arrive
		assertTrue(send(KeyEvent.KEY_PRESSED, 0, KeyEvent.VK_S, KeyEvent.VK_DOWN, KeyEvent.CHAR_UNDEFINED));
		assertTrue(send(KeyEvent.KEY_RELEASED, 0, KeyEvent.VK_S, KeyEvent.VK_DOWN, KeyEvent.CHAR_UNDEFINED));
		assertEquals("s", model.view().getQuery());
		assertEquals(0, model.view().getSelected());

		assertTrue(send(KeyEvent.KEY_PRESSED, InputEvent.SHIFT_DOWN_MASK, KeyEvent.VK_W, KeyEvent.VK_UP, KeyEvent.CHAR_UNDEFINED));
		assertEquals("sW", model.view().getQuery());
		assertEquals(0, model.view().getSelected());
	}

	@Test
	public void numberKeysRewrittenToFunctionKeysAreStillTyped()
	{
		openWithHotkey();
		// Platform Keys sends 1 as F1, and Key Remapping can do the same
		assertTrue(send(KeyEvent.KEY_PRESSED, 0, KeyEvent.VK_1, KeyEvent.VK_F1, KeyEvent.CHAR_UNDEFINED));
		assertTrue(send(KeyEvent.KEY_PRESSED, 0, KeyEvent.VK_NUMPAD2, KeyEvent.VK_F2, KeyEvent.CHAR_UNDEFINED));
		assertTrue(send(KeyEvent.KEY_PRESSED, 0, KeyEvent.VK_SPACE, KeyEvent.VK_CONTROL, KeyEvent.CHAR_UNDEFINED));
		assertEquals("12 ", model.view().getQuery());
		// a real function key types nothing
		assertTrue(send(KeyEvent.KEY_PRESSED, 0, KeyEvent.VK_F5, KeyEvent.CHAR_UNDEFINED));
		assertEquals("12 ", model.view().getQuery());
	}

	@Test
	public void arrowsNavigateAndEscapeCloses()
	{
		openWithHotkey();
		assertTrue(send(KeyEvent.KEY_PRESSED, 0, KeyEvent.VK_DOWN, KeyEvent.CHAR_UNDEFINED));
		assertTrue(send(KeyEvent.KEY_PRESSED, 0, KeyEvent.VK_DOWN, KeyEvent.CHAR_UNDEFINED));
		assertTrue(send(KeyEvent.KEY_PRESSED, 0, KeyEvent.VK_UP, KeyEvent.CHAR_UNDEFINED));
		assertEquals("Zulrah", model.getSelectedSetup().getName());

		assertTrue(send(KeyEvent.KEY_PRESSED, 0, KeyEvent.VK_ESCAPE, (char) 0x1b));
		assertFalse(model.view().isPaletteOpen());
		// the release of the key that closed it doesn't leak to the game either
		assertTrue(send(KeyEvent.KEY_RELEASED, 0, KeyEvent.VK_ESCAPE, (char) 0x1b));
		assertFalse(send(KeyEvent.KEY_PRESSED, 0, KeyEvent.VK_DOWN, KeyEvent.CHAR_UNDEFINED));
	}

	@Test
	public void hotkeyTogglesAndItsCharacterIsNotTyped()
	{
		openWithHotkey();
		assertEquals("", model.view().getQuery());
		assertTrue(send(KeyEvent.KEY_PRESSED, InputEvent.CTRL_DOWN_MASK, KeyEvent.VK_K, (char) 0x0b));
		assertFalse(model.view().isPaletteOpen());
	}

	@Test
	public void keyHeldBeforeOpeningIsStillReleasedToTheGame()
	{
		assertFalse(send(KeyEvent.KEY_PRESSED, 0, KeyEvent.VK_W, 'w'));
		openWithHotkey();
		assertFalse(send(KeyEvent.KEY_RELEASED, 0, KeyEvent.VK_W, 'w'));
	}

	@Test
	public void hotkeyUsesThePlatformModifier()
	{
		platformModifier = InputEvent.META_DOWN_MASK;
		// Ctrl+K is not the shortcut on a Mac, and neither is K alone or Cmd+Shift+K
		assertFalse(send(KeyEvent.KEY_PRESSED, InputEvent.CTRL_DOWN_MASK, KeyEvent.VK_K, (char) 0x0b));
		assertFalse(send(KeyEvent.KEY_PRESSED, 0, KeyEvent.VK_K, 'k'));
		assertFalse(send(KeyEvent.KEY_PRESSED, InputEvent.META_DOWN_MASK | InputEvent.SHIFT_DOWN_MASK, KeyEvent.VK_K, 'K'));
		assertFalse(model.view().isPaletteOpen());

		assertTrue(send(KeyEvent.KEY_PRESSED, InputEvent.META_DOWN_MASK, KeyEvent.VK_K, 'k'));
		assertTrue(model.view().isPaletteOpen());
		// Cmd+K leaves a typed 'k' on some systems; it isn't put in the search box
		assertTrue(send(KeyEvent.KEY_TYPED, InputEvent.META_DOWN_MASK, KeyEvent.VK_UNDEFINED, 'k'));
		assertEquals("", model.view().getQuery());

		assertTrue(send(KeyEvent.KEY_PRESSED, InputEvent.META_DOWN_MASK, KeyEvent.VK_K, 'k'));
		assertFalse(model.view().isPaletteOpen());
	}

	@Test
	public void hotkeyWithoutModifierStaysTypeable()
	{
		requireModifier = false;
		assertFalse(send(KeyEvent.KEY_PRESSED, InputEvent.CTRL_DOWN_MASK, KeyEvent.VK_K, (char) 0x0b));
		assertTrue(send(KeyEvent.KEY_PRESSED, 0, KeyEvent.VK_K, 'k'));
		assertTrue(send(KeyEvent.KEY_TYPED, 0, KeyEvent.VK_UNDEFINED, 'k'));
		assertTrue(model.view().isPaletteOpen());
		assertEquals("", model.view().getQuery());

		// now it's a letter like any other
		tap(KeyEvent.VK_K, 'k');
		assertTrue(model.view().isPaletteOpen());
		assertEquals("k", model.view().getQuery());
	}

	@Test
	public void platformKeysProfileOverridesTheComputer()
	{
		assertEquals(InputEvent.META_DOWN_MASK, PlatformModifier.resolve(null, true));
		assertEquals(InputEvent.CTRL_DOWN_MASK, PlatformModifier.resolve(null, false));
		assertEquals(InputEvent.META_DOWN_MASK, PlatformModifier.resolve("AUTO", true));
		assertEquals(InputEvent.CTRL_DOWN_MASK, PlatformModifier.resolve("WINDOWS", true));
		assertEquals(InputEvent.META_DOWN_MASK, PlatformModifier.resolve("MAC", false));
	}
}

package com.setuppicker;

import com.google.gson.Gson;
import java.awt.Color;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;
import net.runelite.api.gameval.ItemID;
import net.runelite.http.api.RuneLiteAPI;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class SetupRepositoryTest
{
	// The client's gson, which is what serializes colors the way Inventory Setups saves them
	private final Gson gson = RuneLiteAPI.GSON;

	@Test
	public void readsFavoriteColorAndIcon()
	{
		final String json = "{\"inv\":[{\"id\":385,\"q\":5},null],\"eq\":[null,null,null,{\"id\":4151}],"
			+ "\"name\":\"Slayer\",\"hc\":\"#FFFF0000\",\"dc\":\"#FF00FF00\",\"fv\":true,\"iId\":4587}";
		final SetupEntry setup = SetupRepository.parseSetup(gson, "Slayer", json);
		assertEquals("Slayer", setup.getName());
		assertTrue(setup.isFavorite());
		assertEquals(Color.GREEN, setup.getDisplayColor());
		assertEquals(4587, setup.getIconItemId());
	}

	@Test
	public void iconFallsBackToWeapon()
	{
		final String json = "{\"inv\":[],\"eq\":[{\"id\":10828},null,null,{\"id\":4151,\"f\":true}],\"name\":\"Whip\",\"hc\":\"#FFFF0000\"}";
		final SetupEntry setup = SetupRepository.parseSetup(gson, "Whip", json);
		assertFalse(setup.isFavorite());
		assertNull(setup.getDisplayColor());
		assertEquals(4151, setup.getIconItemId());
	}

	@Test
	public void iconFallsBackToCakeWithoutWeapon()
	{
		final String json = "{\"inv\":[],\"eq\":[{\"id\":10828},null,null,null],\"name\":\"Skilling\",\"hc\":\"#FFFF0000\"}";
		assertEquals(ItemID._100GUIDE_GUIDECAKE, SetupRepository.parseSetup(gson, "Skilling", json).getIconItemId());
	}

	@Test
	public void missingOrBrokenDataStillListsTheSetup()
	{
		for (String json : new String[]{null, "", "not json", "[]", "{\"eq\":5}"})
		{
			final SetupEntry setup = SetupRepository.parseSetup(gson, "Mystery", json);
			assertEquals("Mystery", setup.getName());
			assertFalse(setup.isFavorite());
			assertEquals(ItemID._100GUIDE_GUIDECAKE, setup.getIconItemId());
		}
	}

	private static List<String> sortedNames(boolean alphabetical, boolean favoritesFirst)
	{
		final List<SetupEntry> setups = new ArrayList<>();
		setups.add(new SetupEntry("Zulrah", false, null, 1));
		setups.add(new SetupEntry("barrows", false, null, 1));
		setups.add(new SetupEntry("Vorkath", true, null, 1));
		setups.add(new SetupEntry("Araxxor", true, null, 1));
		setups.add(new SetupEntry("Cerberus", false, null, 1));
		return SetupRepository.sort(setups, alphabetical, favoritesFirst).stream().map(SetupEntry::getName).collect(Collectors.toList());
	}

	@Test
	public void sortsByNameIgnoringCaseWithFavoritesOnTop()
	{
		assertEquals(Arrays.asList("Araxxor", "barrows", "Cerberus", "Vorkath", "Zulrah"), sortedNames(true, false));
		assertEquals(Arrays.asList("Araxxor", "Vorkath", "barrows", "Cerberus", "Zulrah"), sortedNames(true, true));
		assertEquals(Arrays.asList("Vorkath", "Araxxor", "Zulrah", "barrows", "Cerberus"), sortedNames(false, true));
		assertEquals(Arrays.asList("Zulrah", "barrows", "Vorkath", "Araxxor", "Cerberus"), sortedNames(false, false));
	}
}

package com.setuppicker;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.io.File;
import java.util.ArrayList;
import java.util.List;
import java.util.function.IntFunction;
import javax.imageio.ImageIO;
import net.runelite.client.ui.FontManager;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * Renders both forms of the picker to build/preview.png, for eyeballing the look without logging in.
 */
public class PickerPreviewTest
{
	private static final int WIDTH = 765;
	private static final int HEIGHT = 503;

	private static List<SetupEntry> setups()
	{
		final List<SetupEntry> setups = new ArrayList<>();
		setups.add(new SetupEntry("Vorkath (dhcb)", true, null, 1));
		setups.add(new SetupEntry("Zulrah", true, new Color(80, 200, 120), 2));
		setups.add(new SetupEntry("Vardorvis", false, null, 3));
		setups.add(new SetupEntry("Tombs of Amascut 300 invocation", false, new Color(230, 190, 90), 4));
		setups.add(new SetupEntry("Barrows", false, null, 5));
		setups.add(new SetupEntry("Slayer melee", false, null, 6));
		setups.add(new SetupEntry("Slayer range", false, null, 7));
		setups.add(new SetupEntry("Slayer burst", false, null, 8));
		for (int i = 0; i < 20; i++)
		{
			setups.add(new SetupEntry("Clue step " + i, false, null, 9 + i));
		}
		return setups;
	}

	// stand-in for item sprites
	private static final IntFunction<BufferedImage> ICONS = id ->
	{
		final BufferedImage image = new BufferedImage(36, 32, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = image.createGraphics();
		g.setColor(Color.getHSBColor(id * 0.13f, 0.6f, 0.9f));
		g.fillOval(6, 4, 24, 24);
		g.dispose();
		return image;
	};

	@Test
	public void renderPreview() throws Exception
	{
		final BufferedImage image = new BufferedImage(WIDTH * 2, HEIGHT, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = image.createGraphics();
		g.setColor(new Color(60, 90, 60));
		g.fillRect(0, 0, WIDTH * 2, HEIGHT);

		// Left: the hotkey popup, mid-search
		final PickerModel palette = new PickerModel();
		palette.setSetups(setups());
		palette.setActiveSetup("Slayer melee");
		palette.openPalette();
		for (char c : "sl".toCharArray())
		{
			palette.typeChar(c);
		}
		final PickerLayout paletteLayout = PickerLayout.computePalette(new Rectangle(WIDTH, HEIGHT), 240,
			palette.view().getSetups().size(), PickerLayout.ROW_HEIGHT_ICONS, 10);
		palette.setVisibleRows(paletteLayout.getVisibleRows());
		palette.moveSelection(1);
		PickerPainter.paint(g, paletteLayout, palette.view(), null, ICONS, FontManager.getRunescapeSmallFont(), "");
		assertTrue(paletteLayout.isPalette());
		assertEquals(3, paletteLayout.getVisibleRows());

		// Right: docked beside a stand-in bank, scrolled, with the mouse over a row
		g.translate(WIDTH, 0);
		final Rectangle bank = new Rectangle(220, 60, 488, 300);
		g.setColor(new Color(73, 64, 52));
		g.fill(bank);
		final PickerModel docked = new PickerModel();
		docked.setSetups(setups());
		docked.setActiveSetup("Zulrah");
		final PickerLayout dockedLayout = PickerLayout.compute(bank, WIDTH, true, 160, false,
			docked.view().getSetups().size(), PickerLayout.ROW_HEIGHT_ICONS);
		docked.setVisibleRows(dockedLayout.getVisibleRows());
		docked.scrollBy(1);
		final Rectangle hovered = dockedLayout.getRow(3);
		PickerPainter.paint(g, dockedLayout, docked.view(), new Point(hovered.x + 20, hovered.y + 5), ICONS,
			FontManager.getRunescapeSmallFont(), "");
		g.dispose();

		// left of the bank, same top, and no taller than it
		assertEquals(bank.x - PickerLayout.GAP, dockedLayout.getBounds().x + dockedLayout.getBounds().width);
		assertEquals(bank.y, dockedLayout.getBounds().y);
		assertTrue(dockedLayout.getBounds().height <= bank.height);
		assertEquals(3, dockedLayout.rowAt(new Point(hovered.x + 20, hovered.y + 5)));

		final File out = new File("build/preview.png");
		out.getParentFile().mkdirs();
		ImageIO.write(image, "png", out);
	}

	@Test
	public void dockedFallsBackWhenThereIsNoRoom()
	{
		// fixed mode: the bank spans the game area, with the inventory to its right
		final Rectangle bank = new Rectangle(12, 2, 488, 334);
		final PickerLayout left = PickerLayout.compute(bank, WIDTH, true, 160, false, 5, 20);
		assertEquals(bank.x + bank.width + PickerLayout.GAP, left.getBounds().x);

		final PickerLayout none = PickerLayout.compute(bank, 512, true, 160, true, 5, 20);
		assertEquals(bank.x, none.getBounds().x);
		assertTrue(none.isCollapsed());
		assertEquals(-1, none.rowAt(new Point(bank.x + 5, bank.y + 5)));
	}
}

package com.setuppicker;

import java.util.ArrayList;
import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;

public class PickerModelTest
{
	private PickerModel model;

	@Before
	public void setUp()
	{
		model = new PickerModel();
		final List<SetupEntry> setups = new ArrayList<>();
		for (String name : new String[]{"Vorkath", "Zulrah", "Vardorvis", "ToA 300", "Barrows", "Slayer melee", "Slayer range"})
		{
			setups.add(new SetupEntry(name, false, null, 1));
		}
		model.setSetups(setups);
		model.setVisibleRows(3);
	}

	private void type(String text)
	{
		for (char c : text.toCharArray())
		{
			model.typeChar(c);
		}
	}

	@Test
	public void typingFiltersIgnoringCase()
	{
		model.openPalette();
		type("SLAY");
		assertEquals(2, model.view().getSetups().size());
		assertEquals("Slayer melee", model.getSelectedSetup().getName());
		assertEquals(7, model.view().getTotal());

		model.backspace();
		model.backspace();
		model.backspace();
		model.backspace();
		assertEquals(7, model.view().getSetups().size());
	}

	@Test
	public void noMatchesSelectsNothing()
	{
		model.openPalette();
		type("zzz");
		assertTrue(model.view().getSetups().isEmpty());
		assertNull(model.getSelectedSetup());
		model.moveSelection(1);
		assertNull(model.getSelectedSetup());
	}

	@Test
	public void selectionStaysInRangeAndOnScreen()
	{
		model.openPalette();
		model.moveSelection(-1);
		assertEquals(0, model.view().getSelected());

		model.moveSelection(4);
		assertEquals("Barrows", model.getSelectedSetup().getName());
		// 3 rows fit, so the selection is the last visible one
		assertEquals(2, model.view().getScroll());

		model.pageSelection(5);
		assertEquals("Slayer range", model.getSelectedSetup().getName());
		assertEquals(4, model.view().getScroll());

		model.pageSelection(-1);
		assertEquals(3, model.view().getSelected());
		assertEquals(3, model.view().getScroll());
	}

	@Test
	public void scrollIsClampedToTheList()
	{
		model.scrollBy(100);
		assertEquals(4, model.view().getScroll());
		model.scrollBy(-100);
		assertEquals(0, model.view().getScroll());

		// everything fits: nothing to scroll
		model.setVisibleRows(20);
		model.scrollBy(3);
		assertEquals(0, model.view().getScroll());
	}

	@Test
	public void openingThePaletteStartsFresh()
	{
		model.setSearchFocused(true);
		type("vor");
		model.openPalette();
		assertTrue(model.view().isPaletteOpen());
		assertTrue(model.view().isSearchFocused());
		assertEquals("", model.view().getQuery());
		assertEquals(7, model.view().getSetups().size());

		model.resetSearch();
		assertFalse(model.view().isPaletteOpen());
		assertFalse(model.view().isSearchFocused());
	}

	@Test
	public void filterSurvivesSetupsReloading()
	{
		model.openPalette();
		type("vor");
		final List<SetupEntry> reloaded = new ArrayList<>();
		reloaded.add(new SetupEntry("Vorkath", true, null, 1));
		reloaded.add(new SetupEntry("Vorkath (dhcb)", false, null, 1));
		reloaded.add(new SetupEntry("Zulrah", false, null, 1));
		model.setSetups(reloaded);
		assertEquals(2, model.view().getSetups().size());
		assertEquals("vor", model.view().getQuery());
	}

	@Test
	public void pickingFromTheUnfilteredListKeepsItsScrollPosition()
	{
		model.scrollBy(4);
		// what clicking a row does, followed by the reload Inventory Setups' config change triggers
		model.resetSearch();
		assertEquals(4, model.view().getScroll());
		model.setSetups(new ArrayList<>(model.view().getSetups()));
		assertEquals(4, model.view().getScroll());

		// the popup starts at the top, and leaves the list beside the bank where it was
		model.openPalette();
		assertEquals(0, model.view().getScroll());
		type("s");
		model.resetSearch();
		assertEquals(4, model.view().getScroll());
	}

	@Test
	public void clearingAFilterGoesBackToTheTop()
	{
		model.setSearchFocused(true);
		type("a");
		model.scrollBy(1);
		model.resetSearch();
		assertEquals(0, model.view().getScroll());
	}

	@Test
	public void scrollIsPulledBackWhenTheListShrinks()
	{
		model.scrollBy(4);
		final List<SetupEntry> fewer = new ArrayList<>(model.view().getSetups().subList(0, 4));
		model.setSetups(fewer);
		assertEquals(1, model.view().getScroll());
	}
}

package com.setuppicker;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class SetupPickerPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(SetupPickerPlugin.class);
		RuneLite.main(args);
	}
}

package com.setuppicker;

import com.google.common.hash.Hashing;
import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.awt.Color;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.events.PluginMessage;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Talks to the Inventory Setups plugin. Hub plugins live in separate classloaders, so everything goes
 * through its PluginMessage API (see InventorySetupsPluginMessageHandler in that plugin) or its saved config.
 */
@Singleton
public class SetupRepository
{
	private static final Logger log = LoggerFactory.getLogger(SetupRepository.class);

	static final String NAMESPACE = "inventory-setups";
	static final String MSG_SETUPS_CHANGED = "setups-changed";
	static final String MSG_ACTIVE_SETUP_CHANGED = "active-setup-changed";
	private static final String MSG_GET_SETUPS = "get-setups";
	private static final String MSG_GET_ACTIVE_SETUP_CONTENTS = "get-active-setup-contents";
	private static final String MSG_VIEW = "view";
	private static final String MSG_CLEAR = "clear";
	private static final String DATA_SETUPS = "setups";
	private static final String DATA_SETUP = "setup";
	static final String DATA_ACTIVE_SETUP = "activeSetup";

	// Inventory Setups stores each setup as json under setupsV3_<murmur3_128 of the name>
	static final String CONFIG_GROUP = "inventorysetups";
	static final String CONFIG_KEY_SETUP_PREFIX = "setupsV3_";

	private final EventBus eventBus;
	private final ConfigManager configManager;
	private final Gson gson;

	@Inject
	SetupRepository(EventBus eventBus, ConfigManager configManager, Gson gson)
	{
		this.eventBus = eventBus;
		this.configManager = configManager;
		this.gson = gson;
	}

	/**
	 * All setups. Empty if Inventory Setups isn't running.
	 *
	 * @param alphabetical sort by name, rather than keeping the order of Inventory Setups' own list
	 */
	public List<SetupEntry> loadSetups(boolean alphabetical, boolean favoritesFirst)
	{
		// post() is synchronous: Inventory Setups fills the collection before it returns
		final List<String> names = new ArrayList<>();
		final Map<String, Object> data = new HashMap<>();
		data.put(DATA_SETUPS, names);
		eventBus.post(new PluginMessage(NAMESPACE, MSG_GET_SETUPS, data));

		final List<SetupEntry> setups = new ArrayList<>(names.size());
		for (String name : names)
		{
			final String hash = Hashing.murmur3_128().hashUnencodedChars(name).toString();
			setups.add(parseSetup(gson, name, configManager.getConfiguration(CONFIG_GROUP, CONFIG_KEY_SETUP_PREFIX + hash)));
		}
		return Collections.unmodifiableList(sort(setups, alphabetical, favoritesFirst));
	}

	static List<SetupEntry> sort(List<SetupEntry> setups, boolean alphabetical, boolean favoritesFirst)
	{
		if (alphabetical)
		{
			setups.sort((a, b) -> String.CASE_INSENSITIVE_ORDER.compare(a.getName(), b.getName()));
		}
		if (favoritesFirst)
		{
			// stable, so favorites and the rest each keep the order they have by now
			setups.sort((a, b) -> Boolean.compare(b.isFavorite(), a.isFavorite()));
		}
		return setups;
	}

	/**
	 * Builds the list entry for a setup from its saved json. The name comes from the API, so a setup whose
	 * json is missing or unreadable still gets listed, just without its icon, color and favorite flag.
	 */
	static SetupEntry parseSetup(Gson gson, String name, String json)
	{
		boolean favorite = false;
		Color displayColor = null;
		int iconItemId = -1;
		try
		{
			final JsonObject setup = json == null ? null : gson.fromJson(json, JsonObject.class);
			if (setup != null)
			{
				favorite = setup.has("fv") && setup.get("fv").getAsBoolean();
				if (setup.has("dc"))
				{
					displayColor = gson.fromJson(setup.get("dc"), Color.class);
				}
				if (setup.has("iId"))
				{
					iconItemId = setup.get("iId").getAsInt();
				}
				if (iconItemId <= 0)
				{
					// Same fallback as Inventory Setups' icon view: the weapon
					iconItemId = itemIdAt(setup.getAsJsonArray("eq"), EquipmentInventorySlot.WEAPON.getSlotIdx());
				}
			}
		}
		catch (RuntimeException e)
		{
			log.debug("Couldn't read saved data for setup {}", name, e);
		}
		if (iconItemId <= 0)
		{
			iconItemId = ItemID._100GUIDE_GUIDECAKE;
		}
		return new SetupEntry(name, favorite, displayColor, iconItemId);
	}

	private static int itemIdAt(JsonArray items, int index)
	{
		if (items == null || index >= items.size())
		{
			return -1;
		}
		// empty slots are saved as null
		final JsonElement item = items.get(index);
		return item.isJsonObject() && item.getAsJsonObject().has("id") ? item.getAsJsonObject().get("id").getAsInt() : -1;
	}

	/**
	 * Name of the setup currently open in Inventory Setups, or "" when there is none or it can't be told
	 * (the API only reports setups that filter the bank). Call on the client thread, where the reply is
	 * synchronous.
	 */
	public String queryActiveSetup()
	{
		final Map<String, Object> data = new HashMap<>();
		data.put("equipmentItemIds", new ArrayList<Integer>());
		data.put("inventoryItemIds", new ArrayList<Integer>());
		data.put("additionalItemIds", new ArrayList<Integer>());
		eventBus.post(new PluginMessage(NAMESPACE, MSG_GET_ACTIVE_SETUP_CONTENTS, data));
		final Object active = data.get(DATA_ACTIVE_SETUP);
		return active instanceof String ? (String) active : "";
	}

	/**
	 * Open a setup in Inventory Setups, as if picked from its side panel.
	 */
	public void open(String name)
	{
		eventBus.post(new PluginMessage(NAMESPACE, MSG_VIEW, Map.of(DATA_SETUP, name)));
	}

	/**
	 * Close a setup, if it is still the one that's open.
	 */
	public void close(String name)
	{
		eventBus.post(new PluginMessage(NAMESPACE, MSG_CLEAR, Map.of(DATA_SETUP, name)));
	}
}

package com.setuppicker;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Draws the picker: as a popup while it has been opened with the hotkey, otherwise beside the bank
 * whenever the bank is open.
 */
@Singleton
public class SetupPickerOverlay extends Overlay
{
	private static final int PALETTE_WIDTH = 240;

	private final Client client;
	private final SetupPickerConfig config;
	private final PickerModel model;
	private final ItemManager itemManager;

	// Layout of the last rendered frame, read by the input listeners. Null while the picker isn't showing.
	private volatile PickerLayout layout;
	private volatile String status = "";

	@Inject
	SetupPickerOverlay(Client client, SetupPickerConfig config, PickerModel model, ItemManager itemManager)
	{
		this.client = client;
		this.config = config;
		this.model = model;
		this.itemManager = itemManager;
		// Positions itself, in canvas coordinates
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	public PickerLayout getLayout()
	{
		return layout;
	}

	/**
	 * Message to show in place of the list when there are no setups.
	 */
	public void setStatus(String status)
	{
		this.status = status;
	}

	public void clearLayout()
	{
		layout = null;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		final PickerModel.View view = model.view();
		final int rowHeight = config.showIcons() ? PickerLayout.ROW_HEIGHT_ICONS : PickerLayout.ROW_HEIGHT_TEXT;
		final PickerLayout newLayout;
		if (view.isPaletteOpen())
		{
			newLayout = PickerLayout.computePalette(new Rectangle(client.getCanvasWidth(), client.getCanvasHeight()),
				PALETTE_WIDTH, view.getSetups().size(), rowHeight, config.popupRows());
		}
		else
		{
			final Widget bank = config.showBesideBank() ? client.getWidget(InterfaceID.Bankmain.UNIVERSE) : null;
			if (bank == null || bank.isHidden())
			{
				layout = null;
				return null;
			}
			newLayout = PickerLayout.compute(bank.getBounds(), client.getCanvasWidth(),
				config.side() == SetupPickerConfig.Side.LEFT, config.width(), config.collapsed(),
				view.getSetups().size(), rowHeight);
		}
		// clamps the scroll position to what now fits, so take the view afterwards
		model.setVisibleRows(newLayout.getVisibleRows());
		layout = newLayout;

		final net.runelite.api.Point mouse = client.getMouseCanvasPosition();
		PickerPainter.paint(graphics, newLayout, model.view(),
			mouse == null ? null : new Point(mouse.getX(), mouse.getY()),
			config.showIcons() ? itemManager::getImage : null,
			FontManager.getRunescapeSmallFont(), status);
		return null;
	}
}

package com.setuppicker;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

/**
 * Takes the keyboard away from the chatbox while the picker's search box has it.
 *
 * <p>The chatbox reads keys through its key listener. The core Key Remapping plugin only acts while that
 * listener is set (its "chatbox focused" check), so with it removed Key Remapping stands down too: it stops
 * turning W/A/S/D into arrow keys, and Enter no longer unlocks its "Press Enter to Chat" input when all it was
 * meant to do was pick a setup. The listener is put back as soon as the search box loses focus.
 *
 * <p>Client thread only.
 */
@Singleton
public class ChatboxKeyGuard
{
	private final Client client;
	private Object[] savedListener;

	@Inject
	ChatboxKeyGuard(Client client)
	{
		this.client = client;
	}

	/**
	 * @param searchFocused whether the picker currently wants the keyboard
	 */
	public void sync(boolean searchFocused)
	{
		if (searchFocused)
		{
			suspend();
		}
		else
		{
			restore();
		}
	}

	private void suspend()
	{
		final Widget chatbox = client.getWidget(InterfaceID.Chatbox.UNIVERSE);
		if (chatbox == null)
		{
			return;
		}
		// Also re-suspends if the game rebuilt the chatbox, and so set the listener again, while searching
		final Object[] listener = chatbox.getOnKeyListener();
		if (listener != null)
		{
			savedListener = listener;
			chatbox.setOnKeyListener((Object[]) null);
		}
	}

	public void restore()
	{
		if (savedListener == null)
		{
			return;
		}
		final Widget chatbox = client.getWidget(InterfaceID.Chatbox.UNIVERSE);
		// If the game has set a listener in the meantime, that one is current: leave it
		if (chatbox != null && chatbox.getOnKeyListener() == null)
		{
			chatbox.setOnKeyListener(savedListener);
		}
		savedListener = null;
	}
}

package com.setuppicker;

import java.awt.Point;
import java.awt.Rectangle;

/**
 * Where the picker's parts are on the canvas for one frame. Shared by painting and mouse hit-testing.
 */
public final class PickerLayout
{
	static final int HEADER_HEIGHT = 20;
	static final int SEARCH_HEIGHT = 20;
	static final int PADDING = 3;
	static final int GAP = 4;
	static final int ROW_HEIGHT_ICONS = 20;
	static final int ROW_HEIGHT_TEXT = 16;
	static final int FOOTER_HEIGHT = 16;

	private final Rectangle bounds;
	private final Rectangle header;
	private final Rectangle search;
	private final Rectangle list;
	private final Rectangle footer;
	private final int rowHeight;
	private final int visibleRows;

	private PickerLayout(Rectangle bounds, Rectangle header, Rectangle search, Rectangle list, Rectangle footer,
		int rowHeight, int visibleRows)
	{
		this.bounds = bounds;
		this.header = header;
		this.search = search;
		this.list = list;
		this.footer = footer;
		this.rowHeight = rowHeight;
		this.visibleRows = visibleRows;
	}

	/**
	 * The hotkey-opened popup: centered horizontally in the game area, in its upper part.
	 *
	 * @param area       the canvas
	 * @param setupCount number of setups to list, after the search is applied
	 * @param maxRows    most rows to show before scrolling
	 */
	public static PickerLayout computePalette(Rectangle area, int width, int setupCount, int rowHeight, int maxRows)
	{
		width = Math.min(width, area.width);
		final int chrome = HEADER_HEIGHT + SEARCH_HEIGHT + FOOTER_HEIGHT + 4 * PADDING;
		final int fittingRows = Math.max(1, (area.height - chrome) / rowHeight);
		final int visibleRows = Math.max(1, Math.min(setupCount, Math.min(maxRows, fittingRows)));

		final int x = area.x + (area.width - width) / 2;
		// Anchored where it would sit with a full list, so it doesn't jump around as typing narrows the results
		final int fullHeight = chrome + Math.min(maxRows, fittingRows) * rowHeight;
		final int y = area.y + Math.max(0, Math.min(area.height / 6, area.height - fullHeight));

		final Rectangle header = new Rectangle(x, y, width, HEADER_HEIGHT);
		final Rectangle search = new Rectangle(x + PADDING, y + HEADER_HEIGHT + PADDING, width - 2 * PADDING, SEARCH_HEIGHT);
		final Rectangle list = new Rectangle(x + PADDING, search.y + search.height + PADDING, width - 2 * PADDING, visibleRows * rowHeight);
		final Rectangle footer = new Rectangle(x + PADDING, list.y + list.height + PADDING, width - 2 * PADDING, FOOTER_HEIGHT);
		final Rectangle bounds = new Rectangle(x, y, width, footer.y + footer.height + PADDING - y);
		return new PickerLayout(bounds, header, search, list, footer, rowHeight, visibleRows);
	}

	/**
	 * The list docked beside the bank.
	 *
	 * @param bank       bounds of the bank interface
	 * @param preferLeft sit left of the bank when both sides have room
	 * @param setupCount number of setups to list, after the search is applied
	 */
	public static PickerLayout compute(Rectangle bank, int canvasWidth, boolean preferLeft, int width,
		boolean collapsed, int setupCount, int rowHeight)
	{
		final int leftX = bank.x - GAP - width;
		final int rightX = bank.x + bank.width + GAP;
		final boolean leftFits = leftX >= 0;
		final boolean rightFits = rightX + width <= canvasWidth;

		final int x;
		if (leftFits && (preferLeft || !rightFits))
		{
			x = leftX;
		}
		else if (rightFits)
		{
			x = rightX;
		}
		else
		{
			// No room on either side (fixed mode): sit on top of the bank's edge instead
			x = preferLeft ? bank.x : bank.x + bank.width - width;
		}
		final int y = bank.y;

		final Rectangle header = new Rectangle(x, y, width, HEADER_HEIGHT);
		if (collapsed)
		{
			return new PickerLayout(header, header, null, null, null, rowHeight, 0);
		}

		final Rectangle search = new Rectangle(x + PADDING, y + HEADER_HEIGHT + PADDING, width - 2 * PADDING, SEARCH_HEIGHT);
		final int listY = search.y + search.height + PADDING;
		final int maxRows = Math.max(1, (bank.y + bank.height - listY - PADDING) / rowHeight);
		// always leave one row's worth of space for the "no setups" message
		final int visibleRows = Math.max(1, Math.min(setupCount, maxRows));
		final Rectangle list = new Rectangle(x + PADDING, listY, width - 2 * PADDING, visibleRows * rowHeight);
		final Rectangle bounds = new Rectangle(x, y, width, list.y + list.height + PADDING - y);
		return new PickerLayout(bounds, header, search, list, null, rowHeight, visibleRows);
	}

	public Rectangle getBounds()
	{
		return bounds;
	}

	public Rectangle getHeader()
	{
		return header;
	}

	/**
	 * The search box, or null when collapsed.
	 */
	public Rectangle getSearch()
	{
		return search;
	}

	/**
	 * The area holding the setup rows, or null when collapsed.
	 */
	public Rectangle getList()
	{
		return list;
	}

	/**
	 * The key hint strip of the popup, or null for the list beside the bank.
	 */
	public Rectangle getFooter()
	{
		return footer;
	}

	public boolean isPalette()
	{
		return footer != null;
	}

	public boolean isCollapsed()
	{
		return list == null;
	}

	public int getRowHeight()
	{
		return rowHeight;
	}

	public int getVisibleRows()
	{
		return visibleRows;
	}

	public Rectangle getRow(int row)
	{
		return new Rectangle(list.x, list.y + row * rowHeight, list.width, rowHeight);
	}

	/**
	 * The visible row under the point, or -1.
	 */
	public int rowAt(Point p)
	{
		if (list == null || !list.contains(p))
		{
			return -1;
		}
		return (p.y - list.y) / rowHeight;
	}
}

package com.setuppicker;

import java.awt.event.InputEvent;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.util.OSType;

/**
 * The "primary" shortcut modifier of the platform being played on: Cmd on a Mac, Ctrl elsewhere.
 *
 * <p>The Platform Keys plugin has a setting to force one platform's keys regardless of the computer. When that
 * plugin hasn't been switched off its choice is followed, so this plugin's shortcut uses the same modifier as its bank search.
 */
@Singleton
public class PlatformModifier
{
	// Platform Keys' config group, its profile setting, and the values that setting takes (its KeyProfile enum)
	private static final String PLATFORM_KEYS_GROUP = "platformkeys";
	private static final String PLATFORM_KEYS_PROFILE = "profile";
	private static final String PROFILE_MAC = "MAC";
	private static final String PROFILE_WINDOWS = "WINDOWS";
	// Where RuneLite records whether the Platform Keys plugin is switched on
	private static final String RUNELITE_GROUP = "runelite";
	private static final String PLATFORM_KEYS_ENABLED = "platformkeysplugin";

	private final ConfigManager configManager;

	@Inject
	PlatformModifier(ConfigManager configManager)
	{
		this.configManager = configManager;
	}

	/**
	 * @return {@link InputEvent#META_DOWN_MASK} or {@link InputEvent#CTRL_DOWN_MASK}
	 */
	public int get()
	{
		// plugins count as on until they have been switched off, so there may be no value at all
		final boolean platformKeysEnabled = !"false".equals(configManager.getConfiguration(RUNELITE_GROUP, PLATFORM_KEYS_ENABLED));
		return resolve(platformKeysEnabled ? configManager.getConfiguration(PLATFORM_KEYS_GROUP, PLATFORM_KEYS_PROFILE) : null,
			OSType.getOSType() == OSType.MacOS);
	}

	/**
	 * @param platformKeysProfile Platform Keys' profile setting, or null when that plugin isn't in use
	 */
	static int resolve(String platformKeysProfile, boolean onMac)
	{
		final boolean mac;
		if (PROFILE_MAC.equals(platformKeysProfile))
		{
			mac = true;
		}
		else if (PROFILE_WINDOWS.equals(platformKeysProfile))
		{
			mac = false;
		}
		else
		{
			// no override, or Platform Keys' own auto-detect
			mac = onMac;
		}
		return mac ? InputEvent.META_DOWN_MASK : InputEvent.CTRL_DOWN_MASK;
	}
}

package com.setuppicker;

import java.awt.event.InputEvent;
import java.awt.event.KeyEvent;
import java.awt.event.MouseEvent;
import java.awt.event.MouseWheelEvent;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.input.KeyListener;
import net.runelite.client.input.MouseAdapter;
import net.runelite.client.input.MouseWheelListener;

/**
 * Mouse and keyboard handling for the picker. Events that land on the picker, and all typing while its
 * search box has focus, are consumed so they don't also reach the game.
 *
 * <p>Key listeners run in the order they were registered, and other plugins' usually come first. Remapping
 * plugins rewrite key presses and consume typed characters before this listener sees them, so it works from
 * the physical key of each press instead. {@link ChatboxKeyGuard} keeps the chatbox out of the way meanwhile.
 */
@Singleton
public class PickerInput extends MouseAdapter implements KeyListener, MouseWheelListener
{
	private static final int MODIFIER_MASK = InputEvent.CTRL_DOWN_MASK | InputEvent.META_DOWN_MASK
		| InputEvent.ALT_DOWN_MASK | InputEvent.SHIFT_DOWN_MASK;

	private final Client client;
	private final SetupPickerPlugin plugin;
	private final SetupPickerConfig config;
	private final SetupPickerOverlay overlay;
	private final PickerModel model;
	private final PlatformModifier platformModifier;

	// The hotkey's own key press can also produce a typed character, which shouldn't end up in the search box
	private boolean swallowNextTyped;
	private final Set<Integer> swallowedPresses = new HashSet<>();

	@Inject
	PickerInput(Client client, SetupPickerPlugin plugin, SetupPickerConfig config, SetupPickerOverlay overlay,
		PickerModel model, PlatformModifier platformModifier)
	{
		this.platformModifier = platformModifier;
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.overlay = overlay;
		this.model = model;
	}

	@Override
	public MouseEvent mousePressed(MouseEvent e)
	{
		final PickerLayout layout = overlay.getLayout();
		if (layout == null || !layout.getBounds().contains(e.getPoint()))
		{
			// clicking back into the game ends the search and dismisses the popup
			if (model.view().isSearchFocused())
			{
				model.resetSearch();
			}
			return e;
		}

		if (SwingUtilities.isLeftMouseButton(e))
		{
			if (layout.isPalette())
			{
				clickRow(layout, e);
			}
			else if (layout.getHeader().contains(e.getPoint()))
			{
				model.resetSearch();
				plugin.setCollapsed(!layout.isCollapsed());
			}
			else if (layout.getSearch() != null && layout.getSearch().contains(e.getPoint()))
			{
				model.setSearchFocused(true);
			}
			else
			{
				clickRow(layout, e);
			}
		}
		e.consume();
		return e;
	}

	private void clickRow(PickerLayout layout, MouseEvent e)
	{
		final int row = layout.rowAt(e.getPoint());
		final PickerModel.View view = model.view();
		final List<SetupEntry> setups = view.getSetups();
		if (row >= 0 && view.getScroll() + row < setups.size())
		{
			plugin.toggleSetup(setups.get(view.getScroll() + row));
			model.resetSearch();
		}
	}

	@Override
	public MouseWheelEvent mouseWheelMoved(MouseWheelEvent e)
	{
		final PickerLayout layout = overlay.getLayout();
		if (layout == null || !layout.getBounds().contains(e.getPoint()))
		{
			return e;
		}
		model.scrollBy(e.getWheelRotation());
		e.consume();
		return e;
	}

	@Override
	public void keyPressed(KeyEvent e)
	{
		final int code = keyCode(e);
		if (isHotkey(e, code))
		{
			if (model.view().isPaletteOpen())
			{
				model.resetSearch();
			}
			else if (client.getGameState() == GameState.LOGGED_IN)
			{
				model.openPalette();
			}
			else
			{
				return;
			}
			swallowNextTyped = true;
			swallow(e, code);
			return;
		}
		// any other key means the hotkey's typed character, if it had one, has been and gone
		swallowNextTyped = false;

		if (!model.view().isSearchFocused())
		{
			return;
		}

		switch (code)
		{
			case KeyEvent.VK_ESCAPE:
				model.resetSearch();
				break;
			case KeyEvent.VK_ENTER:
				final SetupEntry setup = model.getSelectedSetup();
				if (setup != null)
				{
					plugin.toggleSetup(setup);
				}
				model.resetSearch();
				break;
			case KeyEvent.VK_UP:
				model.moveSelection(-1);
				break;
			case KeyEvent.VK_DOWN:
				model.moveSelection(1);
				break;
			case KeyEvent.VK_TAB:
				model.moveSelection(e.isShiftDown() ? -1 : 1);
				break;
			case KeyEvent.VK_PAGE_UP:
				model.pageSelection(-1);
				break;
			case KeyEvent.VK_PAGE_DOWN:
				model.pageSelection(1);
				break;
			case KeyEvent.VK_BACK_SPACE:
				model.backspace();
				break;
			default:
				final char c = typedChar(e, code);
				if (c != 0)
				{
					model.typeChar(c);
				}
				break;
		}
		swallow(e, code);
	}

	@Override
	public void keyTyped(KeyEvent e)
	{
		// The search text is built from key presses (see typedChar), so typed events only need keeping from the game
		if (swallowNextTyped || model.view().isSearchFocused())
		{
			swallowNextTyped = false;
			e.consume();
		}
	}

	@Override
	public void keyReleased(KeyEvent e)
	{
		// Only releases of presses that were swallowed: a key that was already held when the search started
		// (say, a camera key) must still be seen being released by the game
		if (swallowedPresses.remove(keyCode(e)))
		{
			e.consume();
		}
	}

	private void swallow(KeyEvent e, int code)
	{
		swallowedPresses.add(code);
		e.consume();
	}

	/**
	 * The key that was physically pressed. Listeners registered before this one may have rewritten the event's
	 * key code (Key Remapping turns W into Up, for one), but they leave the extended key code alone, which is
	 * also what RuneLite's own keybinds match on.
	 */
	private static int keyCode(KeyEvent e)
	{
		final int extended = e.getExtendedKeyCode();
		return extended != KeyEvent.VK_UNDEFINED ? extended : e.getKeyCode();
	}

	/**
	 * The character a key press types, or 0 for none. Taken from the press rather than from typed events,
	 * because remapping plugins consume those, and blank the character of the presses they rewrite.
	 */
	private static char typedChar(KeyEvent e, int code)
	{
		if (e.isControlDown() || e.isMetaDown())
		{
			return 0;
		}
		final char c = e.getKeyChar();
		if (c != KeyEvent.CHAR_UNDEFINED)
		{
			return c >= ' ' && c != KeyEvent.VK_DELETE ? c : 0;
		}
		// a rewritten press: work the character out from the key
		if (code >= KeyEvent.VK_A && code <= KeyEvent.VK_Z)
		{
			return (char) ((e.isShiftDown() ? 'A' : 'a') + code - KeyEvent.VK_A);
		}
		if (code >= KeyEvent.VK_0 && code <= KeyEvent.VK_9)
		{
			return (char) ('0' + code - KeyEvent.VK_0);
		}
		if (code >= KeyEvent.VK_NUMPAD0 && code <= KeyEvent.VK_NUMPAD9)
		{
			return (char) ('0' + code - KeyEvent.VK_NUMPAD0);
		}
		switch (code)
		{
			case KeyEvent.VK_SPACE:
				return ' ';
			case KeyEvent.VK_MINUS:
				return '-';
			case KeyEvent.VK_EQUALS:
				return '=';
			default:
				return 0;
		}
	}

	private boolean isHotkey(KeyEvent e, int code)
	{
		if (code != config.openKey().getKeyCode() || code == KeyEvent.VK_UNDEFINED)
		{
			return false;
		}
		final int wanted = config.requireModifier() ? platformModifier.get() : 0;
		if ((e.getModifiersEx() & MODIFIER_MASK) != wanted)
		{
			return false;
		}
		// Without a modifier the hotkey is a plain key, which has to stay typeable in the search box
		return wanted != 0 || !model.view().isSearchFocused();
	}
}

package com.setuppicker;

import com.google.inject.Binder;
import com.google.inject.Provides;
import java.util.List;
import java.util.concurrent.atomic.AtomicBoolean;
import javax.inject.Inject;
import net.runelite.api.GameState;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.PluginChanged;
import net.runelite.client.events.PluginMessage;
import net.runelite.client.events.ProfileChanged;
import net.runelite.client.input.KeyManager;
import net.runelite.client.input.MouseManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
	name = "Inventory Setups Picker",
	description = "Open your Inventory Setups from a hotkey-driven, searchable list in game",
	tags = {"inventory", "setups", "bank", "gear", "picker", "hotkey", "search"}
)
public class SetupPickerPlugin extends Plugin
{
	private static final String INVENTORY_SETUPS_PLUGIN_NAME = "Inventory Setups";

	@Inject
	private ClientThread clientThread;

	@Inject
	private ConfigManager configManager;

	@Inject
	private PluginManager pluginManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private MouseManager mouseManager;

	@Inject
	private KeyManager keyManager;

	@Inject
	private ChatboxKeyGuard chatboxKeyGuard;

	@Inject
	private SetupPickerConfig config;

	@Inject
	private SetupRepository repository;

	@Inject
	private PickerModel model;

	@Inject
	private SetupPickerOverlay overlay;

	@Inject
	private PickerInput input;

	private final AtomicBoolean refreshQueued = new AtomicBoolean();

	@Override
	public void configure(Binder binder)
	{
		binder.bind(PickerModel.class).asEagerSingleton();
	}

	@Provides
	SetupPickerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(SetupPickerConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
		mouseManager.registerMouseListener(input);
		mouseManager.registerMouseWheelListener(input);
		keyManager.registerKeyListener(input);

		queueRefresh();
		// Inventory Setups only announces the active setup when it changes, so ask once for the current one
		clientThread.invokeLater(() -> model.setActiveSetup(repository.queryActiveSetup()));
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		mouseManager.unregisterMouseListener(input);
		mouseManager.unregisterMouseWheelListener(input);
		keyManager.unregisterKeyListener(input);
		clientThread.invoke(chatboxKeyGuard::restore);
		overlay.clearLayout();
		model.resetSearch();
	}

	@Subscribe
	public void onPluginMessage(PluginMessage message)
	{
		if (!SetupRepository.NAMESPACE.equals(message.getNamespace()))
		{
			return;
		}
		if (SetupRepository.MSG_SETUPS_CHANGED.equals(message.getName()))
		{
			queueRefresh();
		}
		else if (SetupRepository.MSG_ACTIVE_SETUP_CHANGED.equals(message.getName()))
		{
			final Object active = message.getData().get(SetupRepository.DATA_ACTIVE_SETUP);
			model.setActiveSetup(active instanceof String ? (String) active : "");
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		// Favoriting, recoloring or changing a setup's icon rewrites its saved json without a setups-changed message
		final boolean setupEdited = SetupRepository.CONFIG_GROUP.equals(event.getGroup())
			&& event.getKey().startsWith(SetupRepository.CONFIG_KEY_SETUP_PREFIX);
		if (setupEdited || SetupPickerConfig.GROUP.equals(event.getGroup()))
		{
			queueRefresh();
		}
	}

	@Subscribe
	public void onProfileChanged(ProfileChanged event)
	{
		queueRefresh();
	}

	@Subscribe
	public void onPluginChanged(PluginChanged event)
	{
		if (INVENTORY_SETUPS_PLUGIN_NAME.equals(event.getPlugin().getName()))
		{
			queueRefresh();
		}
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == InterfaceID.BANKMAIN)
		{
			queueRefresh();
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		// the popup is independent of the bank, so only a search in the list beside it ends here
		if (event.getGroupId() == InterfaceID.BANKMAIN && !model.view().isPaletteOpen())
		{
			model.resetSearch();
		}
	}

	@Subscribe
	public void onClientTick(ClientTick event)
	{
		chatboxKeyGuard.sync(model.view().isSearchFocused());
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		// Nothing is drawn outside the game, so don't leave the keyboard captured by an invisible popup
		if (event.getGameState() != GameState.LOGGED_IN)
		{
			model.resetSearch();
		}
	}

	/**
	 * Open the setup, or close it if it's the one already open.
	 */
	void toggleSetup(SetupEntry setup)
	{
		if (setup.getName().equals(model.view().getActiveSetup()))
		{
			clientThread.invoke(() -> repository.close(setup.getName()));
		}
		else
		{
			openSetup(setup);
		}
	}

	void openSetup(SetupEntry setup)
	{
		clientThread.invoke(() -> repository.open(setup.getName()));
	}

	void setCollapsed(boolean collapsed)
	{
		configManager.setConfiguration(SetupPickerConfig.GROUP, SetupPickerConfig.KEY_COLLAPSED, collapsed);
	}

	// Several triggers tend to fire together (e.g. every setup's config key on a profile switch), so
	// collapse them into one reload on the client thread.
	private void queueRefresh()
	{
		if (refreshQueued.compareAndSet(false, true))
		{
			clientThread.invokeLater(() ->
			{
				refreshQueued.set(false);
				final List<SetupEntry> setups = repository.loadSetups(config.alphabetical(), config.favoritesFirst());
				model.setSetups(setups);
				overlay.setStatus(isInventorySetupsEnabled() ? "No setups yet" : "Inventory Setups is off");
			});
		}
	}

	private boolean isInventorySetupsEnabled()
	{
		for (Plugin plugin : pluginManager.getPlugins())
		{
			if (INVENTORY_SETUPS_PLUGIN_NAME.equals(plugin.getName()))
			{
				return pluginManager.isPluginEnabled(plugin);
			}
		}
		return false;
	}
}

package com.setuppicker;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;

/**
 * State of the picker. Written from the client thread (setup data, rendering) and the AWT thread
 * (mouse and keyboard), so every access is synchronized and readers work from an immutable {@link View}.
 */
public class PickerModel
{
	/**
	 * Immutable snapshot of what the picker should currently show.
	 */
	public static final class View
	{
		private final List<SetupEntry> setups;
		private final int total;
		private final String activeSetup;
		private final String query;
		private final boolean searchFocused;
		private final boolean paletteOpen;
		private final int scroll;
		private final int selected;

		private View(List<SetupEntry> setups, int total, String activeSetup, String query, boolean searchFocused,
			boolean paletteOpen, int scroll, int selected)
		{
			this.setups = setups;
			this.total = total;
			this.activeSetup = activeSetup;
			this.query = query;
			this.searchFocused = searchFocused;
			this.paletteOpen = paletteOpen;
			this.scroll = scroll;
			this.selected = selected;
		}

		/**
		 * The setups matching the search, in display order.
		 */
		public List<SetupEntry> getSetups()
		{
			return setups;
		}

		/**
		 * Number of setups before the search was applied.
		 */
		public int getTotal()
		{
			return total;
		}

		public String getActiveSetup()
		{
			return activeSetup;
		}

		public String getQuery()
		{
			return query;
		}

		public boolean isSearchFocused()
		{
			return searchFocused;
		}

		/**
		 * Whether the hotkey-opened popup is showing. It always has search focus while open.
		 */
		public boolean isPaletteOpen()
		{
			return paletteOpen;
		}

		/**
		 * Index into {@link #getSetups()} of the first visible row.
		 */
		public int getScroll()
		{
			return scroll;
		}

		/**
		 * Index into {@link #getSetups()} of the keyboard selection. Only meaningful while searching.
		 */
		public int getSelected()
		{
			return selected;
		}
	}

	private List<SetupEntry> setups = Collections.emptyList();
	private List<SetupEntry> filtered = Collections.emptyList();
	private String activeSetup = "";
	private String query = "";
	private boolean searchFocused;
	private boolean paletteOpen;
	private int scroll;
	private int selected;
	private int visibleRows = 1;
	private int scrollBeforePalette;

	public synchronized View view()
	{
		return new View(filtered, setups.size(), activeSetup, query, searchFocused, paletteOpen, scroll, selected);
	}

	public synchronized void setSetups(List<SetupEntry> newSetups)
	{
		setups = Collections.unmodifiableList(new ArrayList<>(newSetups));
		// a reload (e.g. after a setup is edited) shouldn't move the list under the user
		refilter(false);
	}

	public synchronized void setActiveSetup(String name)
	{
		activeSetup = name == null ? "" : name;
	}

	/**
	 * Told by the overlay how many rows fit, so scrolling can be clamped to it.
	 */
	public synchronized void setVisibleRows(int rows)
	{
		visibleRows = Math.max(1, rows);
		clamp();
	}

	public synchronized void scrollBy(int rows)
	{
		scroll += rows;
		clamp();
	}

	/**
	 * Focus or unfocus the search box of the list beside the bank.
	 */
	public synchronized void setSearchFocused(boolean focused)
	{
		searchFocused = focused;
		if (focused)
		{
			selected = 0;
			scroll = 0;
		}
	}

	/**
	 * Show the popup with an empty search, ready for typing.
	 */
	public synchronized void openPalette()
	{
		if (!paletteOpen)
		{
			scrollBeforePalette = query.isEmpty() ? scroll : 0;
		}
		paletteOpen = true;
		searchFocused = true;
		query = "";
		refilter(true);
	}

	public synchronized void typeChar(char c)
	{
		query += c;
		refilter(true);
	}

	public synchronized void backspace()
	{
		if (!query.isEmpty())
		{
			query = query.substring(0, query.length() - 1);
			refilter(true);
		}
	}

	public synchronized void moveSelection(int delta)
	{
		selected += delta;
		clamp();
		// keep the selection on screen
		if (selected < scroll)
		{
			scroll = selected;
		}
		else if (selected >= scroll + visibleRows)
		{
			scroll = selected - visibleRows + 1;
		}
	}

	/**
	 * Move the selection by whole pages of visible rows.
	 */
	public synchronized void pageSelection(int pages)
	{
		moveSelection(pages * visibleRows);
	}

	/**
	 * The setup the keyboard selection is on, or null when nothing matches the search.
	 */
	public synchronized SetupEntry getSelectedSetup()
	{
		return selected < filtered.size() ? filtered.get(selected) : null;
	}

	/**
	 * Drop the search text and focus and close the popup, e.g. after opening a setup.
	 */
	public synchronized void resetSearch()
	{
		// Back to the full list. If it was already showing, as when a setup is clicked in the list beside
		// the bank, it stays scrolled where it was.
		final boolean wasFiltered = !query.isEmpty();
		searchFocused = false;
		query = "";
		refilter(wasFiltered);
		if (paletteOpen)
		{
			// the popup scrolls on its own; put the list beside the bank back where it was left
			paletteOpen = false;
			scroll = scrollBeforePalette;
			clamp();
		}
	}

	/**
	 * @param resetPosition go back to the top, for when what's listed has changed because of the search
	 */
	private void refilter(boolean resetPosition)
	{
		if (query.isEmpty())
		{
			filtered = setups;
		}
		else
		{
			final String needle = query.toLowerCase(Locale.ROOT);
			final List<SetupEntry> matches = new ArrayList<>();
			for (SetupEntry setup : setups)
			{
				if (setup.getName().toLowerCase(Locale.ROOT).contains(needle))
				{
					matches.add(setup);
				}
			}
			filtered = Collections.unmodifiableList(matches);
		}
		if (resetPosition)
		{
			selected = 0;
			scroll = 0;
		}
		clamp();
	}

	private void clamp()
	{
		scroll = Math.max(0, Math.min(scroll, filtered.size() - visibleRows));
		selected = Math.max(0, Math.min(selected, filtered.size() - 1));
	}
}

package com.setuppicker;

import java.awt.Color;

/**
 * One row in the picker: the bits of an inventory setup needed to list it.
 */
public final class SetupEntry
{
	private final String name;
	private final boolean favorite;
	private final Color displayColor;
	private final int iconItemId;

	public SetupEntry(String name, boolean favorite, Color displayColor, int iconItemId)
	{
		this.name = name;
		this.favorite = favorite;
		this.displayColor = displayColor;
		this.iconItemId = iconItemId;
	}

	public String getName()
	{
		return name;
	}

	public boolean isFavorite()
	{
		return favorite;
	}

	/**
	 * The color the user gave the setup in Inventory Setups, or null for none.
	 */
	public Color getDisplayColor()
	{
		return displayColor;
	}

	public int getIconItemId()
	{
		return iconItemId;
	}
}

package com.setuppicker;

import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Polygon;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.util.List;
import java.util.function.IntFunction;

/**
 * Draws the picker. Has no dependency on the game client so it can be rendered in tests.
 */
public final class PickerPainter
{
	private static final Color BACKGROUND = new Color(40, 34, 26, 240);
	private static final Color BORDER_OUTER = new Color(14, 13, 15);
	private static final Color BORDER_INNER = new Color(87, 80, 64);
	private static final Color HEADER_BACKGROUND = new Color(62, 53, 41);
	private static final Color FIELD_BACKGROUND = new Color(0, 0, 0, 110);
	private static final Color ACCENT = new Color(255, 152, 31);
	private static final Color TEXT = new Color(235, 228, 210);
	private static final Color TEXT_MUTED = new Color(150, 142, 125);
	private static final Color ROW_HOVER = new Color(255, 255, 255, 28);
	private static final Color ROW_ACTIVE = new Color(255, 152, 31, 70);
	private static final Color FAVORITE = new Color(255, 215, 0);
	private static final Color SCROLLBAR = new Color(120, 110, 90);

	private static final int ICON_WIDTH = 18;
	private static final int ICON_HEIGHT = 16;
	private static final int STAR_SIZE = 7;
	private static final int SCROLLBAR_WIDTH = 3;

	private PickerPainter()
	{
	}

	/**
	 * @param mouse  mouse position on the canvas, or null
	 * @param icons  item id to image, or null to draw no icons. May return null for an image that isn't ready.
	 * @param status message for the empty list when there are no setups at all
	 */
	public static void paint(Graphics2D g, PickerLayout layout, PickerModel.View view, Point mouse,
		IntFunction<BufferedImage> icons, Font font, String status)
	{
		g.setFont(font);
		final FontMetrics fm = g.getFontMetrics();

		final Rectangle bounds = layout.getBounds();
		g.setColor(BACKGROUND);
		g.fill(bounds);

		paintHeader(g, fm, layout, view, mouse);

		if (!layout.isCollapsed())
		{
			paintSearch(g, fm, layout.getSearch(), view);
			paintList(g, fm, layout, view, mouse, icons, status);
		}
		if (layout.isPalette())
		{
			final SetupEntry selected = view.getSelected() < view.getSetups().size() ? view.getSetups().get(view.getSelected()) : null;
			final boolean closes = selected != null && selected.getName().equals(view.getActiveSetup());
			g.setColor(TEXT_MUTED);
			g.drawString(truncate(fm, "Up/Down: move   Enter: " + (closes ? "close" : "open") + "   Esc: cancel",
				layout.getFooter().width - 8), layout.getFooter().x + 4, baseline(fm, layout.getFooter()));
		}

		g.setColor(BORDER_INNER);
		g.drawRect(bounds.x + 1, bounds.y + 1, bounds.width - 3, bounds.height - 3);
		g.setColor(BORDER_OUTER);
		g.drawRect(bounds.x, bounds.y, bounds.width - 1, bounds.height - 1);
	}

	private static void paintHeader(Graphics2D g, FontMetrics fm, PickerLayout layout, PickerModel.View view, Point mouse)
	{
		final Rectangle header = layout.getHeader();
		g.setColor(HEADER_BACKGROUND);
		g.fill(header);
		if (!layout.isPalette() && mouse != null && header.contains(mouse))
		{
			g.setColor(ROW_HOVER);
			g.fill(header);
		}

		g.setColor(ACCENT);
		final String title = view.getTotal() > 0 ? "Setups (" + view.getTotal() + ")" : "Setups";
		g.drawString(title, header.x + 7, baseline(fm, header));
		if (layout.isPalette())
		{
			return;
		}

		// collapse arrow: points down when open, right when collapsed
		final int cx = header.x + header.width - 11;
		final int cy = header.y + header.height / 2;
		final Polygon arrow = new Polygon();
		if (layout.isCollapsed())
		{
			arrow.addPoint(cx - 2, cy - 4);
			arrow.addPoint(cx + 3, cy);
			arrow.addPoint(cx - 2, cy + 4);
		}
		else
		{
			arrow.addPoint(cx - 4, cy - 2);
			arrow.addPoint(cx + 4, cy - 2);
			arrow.addPoint(cx, cy + 3);
		}
		g.fill(arrow);
	}

	private static void paintSearch(Graphics2D g, FontMetrics fm, Rectangle search, PickerModel.View view)
	{
		g.setColor(FIELD_BACKGROUND);
		g.fill(search);
		g.setColor(view.isSearchFocused() ? ACCENT : BORDER_INNER);
		g.drawRect(search.x, search.y, search.width - 1, search.height - 1);

		final int textX = search.x + 5;
		final int maxWidth = search.width - 10;
		if (view.getQuery().isEmpty() && !view.isSearchFocused())
		{
			g.setColor(TEXT_MUTED);
			g.drawString("Search...", textX, baseline(fm, search));
			return;
		}

		// show the end of a long query, since that's where the typing happens
		String query = view.getQuery();
		while (!query.isEmpty() && fm.stringWidth(query) > maxWidth - 4)
		{
			query = query.substring(1);
		}
		g.setColor(TEXT);
		g.drawString(query, textX, baseline(fm, search));

		if (view.isSearchFocused() && System.currentTimeMillis() / 500 % 2 == 0)
		{
			final int caretX = textX + fm.stringWidth(query) + 1;
			g.drawLine(caretX, search.y + 4, caretX, search.y + search.height - 5);
		}
	}

	private static void paintList(Graphics2D g, FontMetrics fm, PickerLayout layout, PickerModel.View view, Point mouse,
		IntFunction<BufferedImage> icons, String status)
	{
		final Rectangle list = layout.getList();
		final List<SetupEntry> setups = view.getSetups();

		if (setups.isEmpty())
		{
			final String message = view.getTotal() > 0 ? "No matches" : status;
			g.setColor(TEXT_MUTED);
			g.drawString(truncate(fm, message, list.width - 8), list.x + 4, baseline(fm, list));
			return;
		}

		final boolean scrollable = setups.size() > layout.getVisibleRows();
		final int rowWidth = list.width - (scrollable ? SCROLLBAR_WIDTH + 2 : 0);

		for (int i = 0; i < layout.getVisibleRows(); i++)
		{
			final int index = view.getScroll() + i;
			if (index >= setups.size())
			{
				break;
			}
			final SetupEntry setup = setups.get(index);
			final Rectangle row = layout.getRow(i);
			row.width = rowWidth;

			final boolean active = setup.getName().equals(view.getActiveSetup());
			final boolean hovered = mouse != null && row.contains(mouse);
			final boolean selected = view.isSearchFocused() && index == view.getSelected();
			if (active)
			{
				g.setColor(ROW_ACTIVE);
				g.fill(row);
			}
			if (hovered || selected)
			{
				g.setColor(ROW_HOVER);
				g.fill(row);
			}
			if (selected)
			{
				g.setColor(ACCENT);
				g.drawRect(row.x, row.y, row.width - 1, row.height - 1);
			}

			int textX = row.x + 4;
			if (icons != null)
			{
				final BufferedImage icon = icons.apply(setup.getIconItemId());
				if (icon != null)
				{
					g.drawImage(icon, row.x + 2, row.y + (row.height - ICON_HEIGHT) / 2, ICON_WIDTH, ICON_HEIGHT, null);
				}
				textX = row.x + 2 + ICON_WIDTH + 4;
			}

			int textRight = row.x + row.width - 4;
			if (setup.isFavorite())
			{
				textRight -= STAR_SIZE + 3;
				paintStar(g, textRight + 3 + STAR_SIZE / 2, row.y + row.height / 2);
			}

			g.setColor(setup.getDisplayColor() != null ? setup.getDisplayColor() : (active ? ACCENT : TEXT));
			g.drawString(truncate(fm, setup.getName(), textRight - textX), textX, baseline(fm, row));
		}

		if (scrollable)
		{
			final int barHeight = Math.max(8, list.height * layout.getVisibleRows() / setups.size());
			final int maxScroll = setups.size() - layout.getVisibleRows();
			final int barY = list.y + (list.height - barHeight) * view.getScroll() / maxScroll;
			g.setColor(SCROLLBAR);
			g.fillRect(list.x + list.width - SCROLLBAR_WIDTH, barY, SCROLLBAR_WIDTH, barHeight);
		}
	}

	private static void paintStar(Graphics2D g, int cx, int cy)
	{
		final Polygon star = new Polygon();
		for (int i = 0; i < 10; i++)
		{
			final double radius = i % 2 == 0 ? STAR_SIZE / 2.0 + 0.5 : STAR_SIZE / 4.0;
			final double angle = -Math.PI / 2 + i * Math.PI / 5;
			star.addPoint((int) Math.round(cx + radius * Math.cos(angle)), (int) Math.round(cy + radius * Math.sin(angle)));
		}
		g.setColor(FAVORITE);
		g.fill(star);
	}

	private static int baseline(FontMetrics fm, Rectangle box)
	{
		return box.y + (box.height - fm.getAscent() - fm.getDescent()) / 2 + fm.getAscent();
	}

	private static String truncate(FontMetrics fm, String text, int maxWidth)
	{
		if (fm.stringWidth(text) <= maxWidth)
		{
			return text;
		}
		final String ellipsis = "...";
		String cut = text;
		while (!cut.isEmpty() && fm.stringWidth(cut + ellipsis) > maxWidth)
		{
			cut = cut.substring(0, cut.length() - 1);
		}
		return cut + ellipsis;
	}
}

package com.setuppicker;

import java.awt.event.KeyEvent;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Keybind;
import net.runelite.client.config.Range;

@ConfigGroup(SetupPickerConfig.GROUP)
public interface SetupPickerConfig extends Config
{
	String GROUP = "setuppicker";
	String KEY_COLLAPSED = "collapsed";

	enum Side
	{
		LEFT,
		RIGHT
	}

	@ConfigSection(
		name = "Beside the bank",
		description = "The list shown next to the bank interface",
		position = 10
	)
	String bankSection = "bank";

	@ConfigItem(
		keyName = "hotkey",
		name = "Open hotkey",
		description = "Opens the setup list anywhere in game. Only the key is used; the modifier comes from the next setting."
			+ " Type to filter, Up/Down to move, Enter to open the setup (or close it, if it's the one already open),"
			+ " Esc to cancel.",
		position = 0
	)
	default Keybind openKey()
	{
		return new Keybind(KeyEvent.VK_K, 0);
	}

	@ConfigItem(
		keyName = "requireModifier",
		name = "Require Ctrl/Cmd",
		description = "Require the platform modifier (Cmd on Mac, Ctrl on Windows) together with the open hotkey."
			+ " Follows the Platform Keys plugin's key profile when that plugin is on.",
		position = 1
	)
	default boolean requireModifier()
	{
		return true;
	}

	@Range(min = 3, max = 25)
	@ConfigItem(
		keyName = "popupRows",
		name = "Popup rows",
		description = "How many setups the popup shows before it scrolls",
		position = 2
	)
	default int popupRows()
	{
		return 10;
	}

	@ConfigItem(
		keyName = "showIcons",
		name = "Show icons",
		description = "Show each setup's icon next to its name",
		position = 3
	)
	default boolean showIcons()
	{
		return true;
	}

	@ConfigItem(
		keyName = "alphabetical",
		name = "Sort alphabetically",
		description = "List setups by name. When off, they keep the order of the Inventory Setups side panel's list.",
		position = 4
	)
	default boolean alphabetical()
	{
		return true;
	}

	@ConfigItem(
		keyName = "favoritesFirst",
		name = "Favorites first",
		description = "List favorited setups before the rest",
		position = 5
	)
	default boolean favoritesFirst()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showBesideBank",
		name = "Show beside bank",
		description = "Also show the setup list next to the bank while it is open",
		section = bankSection,
		position = 0
	)
	default boolean showBesideBank()
	{
		return true;
	}

	@ConfigItem(
		keyName = "side",
		name = "Bank side",
		description = "Which side of the bank the list sits on. Falls back to the other side when there is no room.",
		section = bankSection,
		position = 1
	)
	default Side side()
	{
		return Side.LEFT;
	}

	@Range(min = 110, max = 300)
	@ConfigItem(
		keyName = "width",
		name = "Width",
		description = "Width of the list beside the bank in pixels",
		section = bankSection,
		position = 2
	)
	default int width()
	{
		return 160;
	}

	@ConfigItem(
		keyName = KEY_COLLAPSED,
		name = "",
		description = "",
		hidden = true
	)
	default boolean collapsed()
	{
		return false;
	}
}
